#include "symrep_bootstrap.hpp"
#include <unordered_map>
using namespace symrep;
int main(int argc,char**argv){try{require(argc==3,"usage known_sew_control OUT F3words");fs::path o=argv[1];auto t=read(argv[2]);std::unordered_map<uint64_t,Q>f;f.reserve(t.nnz());for(size_t a=0;a<t.dim(0);++a)for(size_t p=t.rowptr()[a];p<t.rowptr()[a+1];++p){uint64_t q=a;for(size_t k=0;k<5;++k)q=88*q+t.index(p)[k];f.emplace(q,t.val(p));}t.clear();auto b=read_matrix(o/"suffix_TF175_physical.wxf");PrivateCarrierChart c(b);require(c.complete,"no suffix physical privatechart");std::ifstream in(o/"dual_words_w4.txt");size_t n,w;in>>n>>w;require(n==1548&&w==4,"prefixchart");Mat s(n,175);for(size_t r=0;r<n;++r){uint64_t q=0;for(size_t k=0;k<4;++k){size_t a;in>>a;q=88*q+a-1;}std::string v;in>>v;Q d(v);for(size_t j=0;j<175;++j){auto it=f.find(q*88*88+c.columns[j]);if(it!=f.end())s[r].push_back(index(j),it->second/(d*c.values[j]));}}write(o/"known_F3_FEC4_TF175.wxf",s);auto origin=read_matrix(o/"affine_tail_w6_control_TF175_origin.wxf"),e=read_matrix(o/"lastpair_E.wxf");require(equal(mul(s,e),mul(origin,e)),"independent lowerloop affine source residual");std::cout<<"COMPLETE knownF3_sew_nnz="<<s.nnz()<<" source_tail_match=pass physical_privatechart=pass"<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
